actions.script:
const out = ec.service.sync().name('org.moqui.maps.MapServices.get#EffectiveConfig').requireNewTransaction(true)
    .parameters({profileId: profileId || null, layerIds: null, recordLayers: false}).call()
if (ec.message.hasError()) { const errors = ec.message.getErrorsString(); ec.message.clearErrors(); ec.web.sendJsonResponse({errors}) }
else ec.web.sendJsonResponse(out.config || {})

const flag = value => [].concat(value ?? []).map(String).includes('Y') ? 'Y' : 'N'
packageRequest = {name: name || null, west, south, east, north, minZoom, maxZoom, profileId: profileId || null,
    basemapLayerIds: [].concat(basemapLayerIds ?? []).flatMap(value => String(value).split(',')).map(id => id.trim()).filter(id => id),
    includePlaces: flag(includePlaces), includeOverlays: flag(includeOverlays), includePostal: flag(includePostal),
    includeOverture: flag(includeOverture)}
const service = estimateButton ? 'estimate#Package' : 'create#Package'
const out = ec.service.sync().name('org.moqui.maps.MapSourceServices.' + service).parameters(packageRequest).call()
if (!ec.message.hasError()) {
    const estimate = out?.estimate || {}
    const size = ec.l10n.localize('about') + ' ' + (estimate.bytesText || '') + ', ' + (estimate.tileCount || 0) + ' ' + ec.l10n.localize('tiles')
    if (!out?.applied) ec.message.addMessage(out?.reason || ec.l10n.localize('The offline map was not made'), 'warning')
    else if (estimateButton) ec.message.addMessage(ec.l10n.localize('This offline map would be') + ' ' + size, 'info')
    else ec.message.addMessage(ec.l10n.localize('The offline map is being built') + ' (' + size + '): '
        + ec.l10n.localize('you are told when it is ready'), 'success')
}

const access = ec.service.sync().name('org.moqui.maps.MapSourceServices.get#PackageAccess')
    .parameters({packageId: String(packageId ?? ''), revision: String(revision ?? ''),
        method: String(ec.web.request?.method ?? 'GET')}).call()
if (ec.message.hasError() || !access?.ok) {
    const status = ec.message.hasError() ? 404 : Number(access.status) || 404
    ec.message.clearErrors()
    ec.web.sendJsonError(status, status === 409 ? 'The offline map was built again: download it again' : 'Offline map not available')
} else {
    // the owner was checked above; the file is read as the framework
    const wasDisabled = ec.artifactExecution.disableAuthz()
    try { ec.web.sendPinnedResourceResponse(access.location, access.tag, access.size, false, access.fileName) }
    finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }
}

const config = effective?.config || {}
basemapOptions = Array.from(config.profile?.basemaps || []).filter(entry => entry.kind === 'pmtiles')
    .map(entry => ({value: entry.id, label: entry.label || entry.id}))
// the region: the one asked for, else the map's initial view (its extent, or a box around its center at its zoom)
const asked = [west, south, east, north].map(value => value === '' || value == null ? NaN : Number(value))
let box = asked.every(Number.isFinite) ? asked : null
if (!box && Array.isArray(config.extent)) box = config.extent.map(Number)
if (!box) {
    const center = Array.isArray(config.center) ? config.center.map(Number) : [0, 20]
    const half = Math.min(180, 180 / Math.pow(2, Math.max(0, Number(config.zoom ?? 2) - 1)))
    box = [Math.max(-180, center[0] - half), Math.max(-85, center[1] - half / 2), Math.min(180, center[0] + half), Math.min(85, center[1] + half / 2)]
}
const round = value => String(Math.round(Number(value) * 10000) / 10000)
regionValues = {name: name || '', west: round(box[0]), south: round(box[1]), east: round(box[2]), north: round(box[3]),
    minZoom: minZoom || '0', maxZoom: maxZoom || '14', profileId: profileId || '', basemapLayerIds: [],
    includePlaces: 'Y', includeOverlays: 'Y', includePostal: 'Y', includeOverture: 'Y'}
regionExtent = [box[0], box[1], box[2], box[3]].join(',')
const [w, s, e, n] = box
regionFeatures = {type: 'FeatureCollection', features: [{type: 'Feature', id: 'region', properties: {label: ec.l10n.localize('The offline map\'s region')},
    geometry: {type: 'Polygon', coordinates: [[[w, s], [e, s], [e, n], [w, n], [w, s]]]}}]}
zoomOptions = Array.from({length: 17}, (unused, zoom) => ({value: String(zoom), label: String(zoom)}))
